{
  "hypothesis": "When small-cap stocks experience abnormally high-volume days, short-term reversals follow in next-period cross-sectional returns.",
  "factors": [
    {
      "name": "vol_reversal_rank",
      "expression": "RANK(TS_ZSCORE(TS_ARGMAX($volume, 5), 20))",
      "explanation": "Measures the rank of the most volume-intensive day within a 5-day window, standardized across 20 days, to capture reversal potential after high-volume events."
    },
    {
      "name": "vol_dispersion_signal",
      "expression": "TS_QUANTILE($return, 20, 0.9) - TS_QUANTILE($return, 20, 0.1) / TS_MAD($volume, 20)",
      "explanation": "Calculates the spread between top and bottom return deciles relative to volume dispersion, highlighting asymmetric return patterns after volatile trading."
    },
    {
      "name": "vol_residual_momentum",
      "expression": "REGRESI($return, $volume, 20) * TS_PCTCHANGE($volume, 5)",
      "explanation": "Captures the residual momentum from volume-regressed returns, amplified by recent volume changes, to identify persistent reversal dynamics."
    },
    {
      "name": "highday_reversal_weighted",
      "expression": "SUMIF(TS_ARGMAX($volume, 5), 20, $return) / SUMIF(TS_ARGMIN($volume, 5), 20, $return)",
      "explanation": "Weights returns from high-volume days against low-volume days to highlight directional shifts following extreme trading activity."
    },
    {
      "name": "vol_skew_momentum",
      "expression": "TS_SKEW($return, 20) * DELAY(TS_ZSCORE($volume, 5), 1)",
      "explanation": "Combines return skewness with lagged volume z-scores to detect asymmetries in price behavior after high-volume events."
    },
    {
      "name": "vol_kurt_reversal",
      "expression": "TS_KURT($return, 20) - TS_KURT($volume, 20) * TS_PCTCHANGE($return, 5)",
      "explanation": "Compares return kurtosis to volume kurtosis, adjusted by recent return changes, to isolate reversal signals from volatility regimes."
    }
  ]
}

