{
  "hypothesis": "Short-term reversal after abnormally high-volume days in small-cap stocks",
  "factors": [
    {
      "name": "vol_reversal_rank",
      "expression": "RANK(TS_ZSCORE(DELAY($volume, 1), 20)) * TS_PCTCHANGE($return, 5)",
      "explanation": "Measures the reversal effect by ranking the z-score of lagged volume and multiplying it with recent return change, exploring the depth axis"
    },
    {
      "name": "vol_skew_factor",
      "expression": "TS_SKEW($volume, 10) - TS_SKEW($volume, 30) + TS_CORR($volume, $return, 20)",
      "explanation": "Explores the shape axis by comparing skewness of volume across different windows and correlating volume with returns"
    },
    {
      "name": "vol_resid_factor",
      "expression": "REGRESI($return, $volume, 60) + TS_MAD($return, 20)",
      "explanation": "Uses the residual from regressing returns on volume and adds a measure of dispersion, exploring the residual axis"
    },
    {
      "name": "vol_quantile_diff",
      "expression": "TS_QUANTILE($volume, 20, 0.9) - TS_QUANTILE($volume, 20, 0.1)",
      "explanation": "Examines the order statistics axis by measuring the gap between high and low volume quantiles"
    },
    {
      "name": "vol_decay_factor",
      "expression": "DECAYLINEAR(TS_ARGMAX($volume, 10), 5) * TS_PCTCHANGE($return, 1)",
      "explanation": "Combines the inversion and depth axes by weighting the maximum volume day and multiplying with daily return change"
    },
    {
      "name": "vol_neglect_factor",
      "expression": "INV(LOG(SUMAC($volume, 10))) + TS_COVARIANCE($volume, $return, 30)",
      "explanation": "Uses an overlooked operator (LOG and SUMAC) to create a novel volume measure and combines it with covariance"
    }
  ]
}

